package mz.bam.seeky.android;
import java.io.*;import java.nio.charset.StandardCharsets;import org.json.JSONObject;
/** Trusted host injection; document scripts remain blocked by an HTTP CSP. No JavaScript interface. */
final class WebSpeechHighlight {
 final OriginalDocument owner;int loadedGeneration=-1,pendingGeneration=-1,preparedGeneration=-1,preparing=-1;String text="";static volatile String script;
 WebSpeechHighlight(OriginalDocument owner){this.owner=owner;}
 void prepare(){if(owner.closed||owner.view==null||owner.loading||preparedGeneration==owner.generation||preparing==owner.generation)return;int expected=owner.generation;preparing=expected;owner.a.worker.execute(()->{try{String helper=script;if(helper==null)try(InputStream in=owner.a.getAssets().open("reader/speech-highlight.js")){helper=new String(ContentText.read(in,65536),StandardCharsets.UTF_8);script=helper;}String code=helper;owner.a.ui(()->{if(owner.closed||owner.view==null||owner.generation!=expected)return;owner.view.evaluateJavascript(code,result->{preparedGeneration=expected;preparing=-1;owner.a.chrome.changed();});});}catch(IOException e){preparing=-1;AppDiagnostics.record(owner.a,"reading-selection",e);}});}
 void update(SpeechEvents.State state,boolean follow){prepare();if(owner.view==null||owner.loading||!owner.active)return;if(!state.active||!state.uri.equals(owner.a.uri.toString())||state.part!=owner.a.chrome.current()){owner.view.evaluateJavascript("window.seekySpeech&&window.seekySpeech.clear()",null);return;}ReaderTools tools=owner.a.tools;if(tools==null||tools.draft==null||tools.segment!=state.part)return;String source=tools.draft.text;if(source.length()>524288)return;
  if(loadedGeneration!=owner.generation||!source.equals(text)){final int expected=owner.generation;if(pendingGeneration==expected)return;pendingGeneration=expected;owner.a.worker.execute(()->{try{String helper=script;if(helper==null)try(InputStream in=owner.a.getAssets().open("reader/speech-highlight.js")){helper=new String(ContentText.read(in,65536),StandardCharsets.UTF_8);script=helper;}final String code=helper;owner.a.ui(()->{if(owner.closed||!owner.active||owner.generation!=expected||owner.view==null)return;loadedGeneration=expected;pendingGeneration=-1;text=source;owner.view.evaluateJavascript(code+";window.seekySpeech.init("+JSONObject.quote(source)+")",result->draw(SpeechEvents.state,follow));});}catch(IOException e){AppDiagnostics.record(owner.a,"reading-highlight",e);}});return;}draw(state,follow);
 }
 void draw(SpeechEvents.State state,boolean follow){if(owner.view==null||owner.closed||state.part!=owner.a.chrome.current())return;int end=state.end>state.offset?state.end:wordEnd(text,state.offset);owner.view.evaluateJavascript("window.seekySpeech&&window.seekySpeech.show("+state.offset+","+end+","+follow+")",null);}
 static int wordEnd(String text,int start){int end=Math.max(0,Math.min(start,text.length()));while(end<text.length()&&end-start<240&&!Character.isWhitespace(text.charAt(end)))end++;return Math.max(start+1,end);}
}
